// 752-801 async GirlA06_at. TH18 v1.00a Stage 6 mid-stage wave 6.
// Source ranks 0..3 = Easy/Normal/Hard/Lunatic.
const TIME_LIMIT: int = 1660;
const SOURCE_LIMIT: int = 1540; // no source timeout; local estimate incl. trailing bullets
const TH18_BALL2: int = 432;    // source etSprite type 5, color 2 (touhou-bullets.ecl)

// GirlA06_at 771: type2 a=1 is the birth ANIM, omitted by the approved policy.
// 772 WAIT 100 and 773 VELTIME 100 -> 3.2 are explicit and kept: bullets keep the
// 0.5 launch speed for 100 frames, then ramp linearly along the same angle.
// The birth ANIM's -4*0.5 = -2px backward displacement is kept at the spawn point.
const BIRTH_BACK: fx = 2fx;
xformdef GIRL_BULLET {
    wait(100);
    step_speed(3.2fx, 100 + 65536 * EASE_LINEAR);
}

async sub girl_fire() {
    // GirlA06_at 755: wait(10); 756-770 etNew(0)/etAim(0,0)/etSprite(5,2)/
    // etCount(rank count,1)/etAngle/etSpeed(0.5,1.0, M=1) and EX 771-773.
    wait(10);
    var rank: int = global(GVAR_RANK);
    var n: int = 1;
    if rank >= 2 { n = 3; }       // 759-766: E1 N1 H3 LO3
    var cooldown: int = 80;       // 787-794: E160, N/H80, L60
    if rank == 0 { cooldown = 160; }
    if rank == 3 { cooldown = 60; }
    for outer in 0..10 {          // 775 $A=10
        for inner in 0..10 {      // 778 $B=10
            // 781 etOffsetRad: RANDRAD then RANDF2*32, sampled in source order.
            var oa: angle = rand(65536) as angle;
            var u: fx = (rand(65536) - 32768) as fx;
            var od: fx = (u / 32768) * 32fx;
            var sx: fx = $self_x + od * cos(oa);
            var sy: fx = $self_y + od * sin(oa);
            // 782 etAngle: RANDF2*2deg base offset, 60deg route spacing, mode 0 fan.
            var alpha: angle = (rand(729) - 364) as angle;
            var aim: angle = atan2($player_y - sy, $player_x - sx);
            var a0: angle = aim + alpha;
            fire_with_backshift(a0, sx, sy);
            if n == 3 {
                fire_with_backshift(a0 - 60deg, sx, sy);
                fire_with_backshift(a0 + 60deg, sx, sy);
            }
            wait(2);              // 783
        }
        wait(cooldown);           // 796 wait([-1])
    }
}

// Birth ANIM displacement runs backward along the bullet's own angle; applied
// before the WAIT/VELTIME program so the flight phase starts at the same point.
sub fire_with_backshift(a: angle, sx: fx, sy: fx) {
    var bx: fx = sx - BIRTH_BACK * cos(a);
    var by: fx = sy - BIRTH_BACK * sin(a);
    _ = fire(TH18_BALL2, 2, bx, by, 0.5fx, a, GIRL_BULLET, none);
}

async sub girl_main(turn: angle) {
    // 733-737 anmSelect/anmSetMain/dropExtra/unknown573/ins_574: presentation and
    // ordinary drops, omitted per policy. 738-739 source hitboxes 24/16 -> r12/r8.
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 740 moveVel(pi/2, 1.4); 741 async GirlA06_at.
    move_vel(0, 90deg, 1.4fx, EASE_LINEAR);
    spawn girl_fire();
    // 742 wait(120); 743 moveVelTime(360, mode7, -1deg, 0).
    // mode7 adds the angle delta every frame; the mirrored M enemy turns +1deg.
    wait(120);
    var steps: int = 360;
    while steps > 0 {
        move_angle(0, $self_angle + turn, EASE_LINEAR);
        wait(1);
        steps = steps - 1;
    }
    // 744-748 goto wait(1000) loop; target offscreen cull ends the enemy.
    loop { wait(1000); }
}

async sub pattern() {
    wait(120); // required opening buffer; source MainSub05 starts after this
    // 1294-1303: 8 rounds, I0=32 then +16 each round; paired enmCreate/enmCreateM.
    var i0: fx = 32fx;
    var remaining: int = 8;
    while remaining > 0 {
        // 1298-1299: _f(-192+$I0) and _f(192-$I0), y=-32; I0 evaluated per creation.
        // enmCreateM gives the right member its mirror bit, i.e. reflected motion.
        _ = spawn_enemy(-192fx + i0, -32fx, 500, 0, 0, 0, girl_main(-1deg));
        _ = spawn_enemy(192fx - i0, -32fx, 500, 0, 0, 0, girl_main(1deg));
        i0 = i0 + 16fx;           // 1300
        wait(40);                 // 1301
        remaining = remaining - 1;
    }
    loop { wait(1); }
}

async sub boss_main() {
    // Extra control enemy at (0,0), body contact disabled; real GirlA06 keep
    // their source hitboxes. Source starts after the 120-frame opening buffer.
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
